WITH items AS (SELECT order_id,sum(qty)::BIGINT AS ordered_qty FROM order_items GROUP BY order_id), refunds AS (SELECT i.order_id,sum(r.qty)::BIGINT AS refunded_qty,sum(r.refund_amount)::DECIMAL(38,2) AS refund_amount FROM returns r JOIN order_items i USING(order_item_id) WHERE r.status='refunded' GROUP BY i.order_id), paid AS (SELECT order_id,sum(amount)::DECIMAL(38,2) AS paid_amount FROM payments WHERE status='succeeded' GROUP BY order_id) SELECT o.order_id,coalesce(i.ordered_qty,0)::BIGINT AS ordered_qty,coalesce(r.refunded_qty,0)::BIGINT AS refunded_qty,coalesce(p.paid_amount,0)::DECIMAL(38,2) AS paid_amount,coalesce(r.refund_amount,0)::DECIMAL(38,2) AS refund_amount FROM orders o LEFT JOIN items i USING(order_id) LEFT JOIN refunds r USING(order_id) LEFT JOIN paid p USING(order_id) ORDER BY o.order_id;
